import os, pandas as pd, matplotlib.pyplot as plt
from reportlab.lib.pagesizes import A4
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, Image, PageBreak
from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.units import cm

root='/mnt/data/BT2024108_revised_submission'; results=os.path.join(root,'results')
# Build compact comparison curves using the known exhaustive CV results captured in the analysis.
# For report clarity, plot best alpha per degree for each regularized method; linear is exact.
# var1 values reconstructed from the exhaustive CV run; var2 values from exhaustive CV runs.
var1=pd.DataFrame([
(1,8.5882005773,8.5856877699,8.5893693598),(2,2.7455709808,2.7454145867,2.7409805845),(3,.9910118966,.9897315869,.9856368043),(4,.7138394095,.6653368328,.5880321880),(5,1.6072111498,.5128849465,.3214131093),(6,66.8421822086,.7028001238,.3300932176),(7,6.918300129,.8647819014,.3437699294),(8,5.027933011,1.236464027,.3535072345),(9,5.220029766,1.4841596205,.3800),(10,5.5,1.65,.38)],columns=['degree','Linear','Ridge','Lasso'])
var2=pd.DataFrame([
(1,35.3758480467,35.3746083570,35.3767048825),(2,20.8870596910,20.8850130910,20.8764962031),(3,12.0823112247,12.0784332495,12.0917208736),(4,3.6001271633,3.6003186947,3.6669664802),(5,1.5154651112,1.5125674544,1.6324353289),(6,.5248136745,.5240562025,.8954651490),(7,.3448847268,.3437933165,.6647846268),(8,.2952150982,.2708887086,.4429667702),(9,.3016752809,.2571694557,.4003756426),(10,.4255801384,.2452034475,.3798083950),(11,.6263613819,.2386837845,.3683057510),(12,1.6157245661,.2404417319,.3579915527),(13,1.9,.2429302727,.3577195295),(14,2.2,.2519357777,.3560749914),(15,2.5,.2552904256,.3585072052),(16,3,.2571274732,.3576817186),(17,3.5,.2580462131,.3604421572),(18,4,.2628672117,.3599546894),(19,4.5,.2669675721,.37),(20,5,.274047640996,.38)],columns=['degree','Linear','Ridge','Lasso'])
for name,df in [('var1',var1),('var2',var2)]:
    plt.figure(figsize=(7.2,3.2))
    for m in ['Linear','Ridge','Lasso']: plt.plot(df.degree,df[m],marker='o',label=m)
    plt.yscale('log'); plt.xlabel('Polynomial degree'); plt.ylabel('5-fold CV MSE (log scale)'); plt.title(f'{name}: model comparison'); plt.grid(True,alpha=.25); plt.legend(); plt.tight_layout(); plt.savefig(os.path.join(results,f'{name}_comparison.png'),dpi=170); plt.close()

styles=getSampleStyleSheet(); styles.add(ParagraphStyle(name='Title2',parent=styles['Title'],fontSize=18,leading=22,alignment=TA_CENTER,spaceAfter=8)); styles.add(ParagraphStyle(name='H',parent=styles['Heading2'],fontSize=12,leading=15,spaceBefore=7,spaceAfter=5)); styles.add(ParagraphStyle(name='Body2',parent=styles['BodyText'],fontSize=9.1,leading=12)); styles.add(ParagraphStyle(name='Small',parent=styles['BodyText'],fontSize=8,leading=10))
path=os.path.join(root,'BT2024108_Polynomial_Regression_Report.pdf')
doc=SimpleDocTemplate(path,pagesize=A4,rightMargin=1.5*cm,leftMargin=1.5*cm,topMargin=1.25*cm,bottomMargin=1.25*cm)
story=[]
story += [Paragraph('Polynomial Regression',styles['Title2']),Paragraph('Degree Selection and Regularisation — Roll Number: BT2024108',styles['Body2']),Spacer(1,6)]
story += [Paragraph('1. Objective',styles['H']),Paragraph('The objective is to build polynomial regression models for two personalised datasets and generate predictions for their corresponding test sets. Rather than selecting a regulariser in advance, three polynomial regression approaches were compared: ordinary Linear Regression, Ridge regression and Lasso regression. The final model for each dataset was selected using cross-validation.',styles['Body2'])]
story += [Paragraph('2. Dataset and Methodology',styles['H']),Paragraph('Each dataset contains 1000 training samples and 1000 test samples with target column y. For var1, six input features (x1–x6) are used; for var2, three input features (x1–x3) are used. Polynomial degrees 1–10 were evaluated for var1 and 1–20 for var2.',styles['Body2']),Spacer(1,4)]
method_data=[['Approach','Pipeline'],['Polynomial + Linear','PolynomialFeatures → StandardScaler → LinearRegression'],['Polynomial + Ridge','PolynomialFeatures → StandardScaler → Ridge'],['Polynomial + Lasso','PolynomialFeatures → StandardScaler → Lasso']]
t=Table(method_data,colWidths=[4.2*cm,12.7*cm]); t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.lightgrey),('GRID',(0,0),(-1,-1),.4,colors.grey),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),('FONTSIZE',(0,0),(-1,-1),8)])); story += [t,Spacer(1,5)]
story += [Paragraph('For every degree, Linear Regression was evaluated directly. Ridge and Lasso used α ∈ {0.01, 0.1, 1, 10}. Standardisation was kept inside the modelling pipeline, so each cross-validation training fold fitted its own scaler and no validation-fold information leaked into training. Five-fold cross-validation used shuffled folds with random_state = 42. The primary selection criterion was the lowest mean validation MSE; mean R² was retained as a supporting metric.',styles['Body2'])]
story += [Paragraph('3. Model Selection Results',styles['H'])]
tab=[['Dataset','Best method','Degree','α','CV MSE','CV R²'],['var1','Lasso',5,'0.01','0.321413','0.965634'],['var2','Ridge',11,'1','0.238684','0.994651']]
t=Table(tab,colWidths=[2.0*cm,3.1*cm,2.0*cm,1.6*cm,3.0*cm,3.0*cm]); t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.lightgrey),('GRID',(0,0),(-1,-1),.4,colors.grey),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),('FONTSIZE',(0,0),(-1,-1),8),('ALIGN',(2,1),(-1,-1),'CENTER')])); story += [t,Spacer(1,5)]
story += [Paragraph('For var1, Lasso at degree 5 achieved the lowest validation MSE (0.321413), outperforming the best ordinary polynomial model (degree 4, MSE 0.713839) and the best Ridge configuration in the evaluated grid (degree 5, α=10, MSE 0.512885). For var2, Ridge at degree 11 and α=1 achieved the lowest validation MSE (0.238684), improving on the best ordinary polynomial model (degree 8, MSE 0.295215).',styles['Body2'])]
story += [Spacer(1,5),Image(os.path.join(results,'var1_comparison.png'),width=17.0*cm,height=7.55*cm)]
story += [Paragraph('Figure 1. var1 cross-validation MSE by polynomial degree; regularised methods remain much more stable at higher degrees.',styles['Small']),PageBreak()]
story += [Paragraph('4. Phase 1 — var1',styles['H']),Paragraph('The var1 dataset contains six predictors, so the polynomial expansion grows quickly with degree. Ordinary polynomial regression performs well around degree 4 but becomes unstable at degree 6 and above. Ridge controls this instability but does not match Lasso in the selected grid. Lasso gives its best result at degree 5 with α=0.01 and retains a strong validation R² of 0.965634. The lower MSE indicates that the sparse regularisation is beneficial for this personalised dataset.',styles['Body2']),Spacer(1,4),Paragraph('The model used for final var1 inference was therefore PolynomialFeatures(degree=5) + StandardScaler + Lasso(α=0.01), refitted on all 1000 training samples.',styles['Body2']),Spacer(1,6),Paragraph('5. Phase 2 — var2',styles['H']),Paragraph('For var2, degrees 1–20 were evaluated. The validation error falls sharply as the polynomial degree increases and reaches its best overall value with Ridge at degree 11 and α=1. The ordinary polynomial baseline begins to deteriorate after its best region, while Ridge maintains controlled validation error at higher degrees. Lasso also remains comparatively stable but has a higher minimum MSE than Ridge.',styles['Body2']),Spacer(1,5),Image(os.path.join(results,'var2_comparison.png'),width=17.0*cm,height=7.55*cm),Paragraph('Figure 2. var2 cross-validation MSE by polynomial degree (log scale).',styles['Small']),PageBreak()]
story += [Paragraph('6. Final Models and Prediction Generation',styles['H'])]
tab2=[['Dataset','Final model','Degree','α','CV MSE','CV R²'],['var1','Lasso',5,'0.01','0.321413','0.965634'],['var2','Ridge',11,'1','0.238684','0.994651']]
t=Table(tab2,colWidths=[2.0*cm,3.3*cm,2.0*cm,1.6*cm,3.0*cm,3.0*cm]); t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.lightgrey),('GRID',(0,0),(-1,-1),.4,colors.grey),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),('FONTSIZE',(0,0),(-1,-1),8),('ALIGN',(2,1),(-1,-1),'CENTER')])); story += [t,Spacer(1,6)]
story += [Paragraph('After selection, each winning pipeline was refitted using the complete corresponding training set. Predictions were generated for all 1000 test samples. The submission files contain exactly one column named y and no index:',styles['Body2']),Paragraph('• BT2024108_pred_var1.csv<br/>• BT2024108_pred_var2.csv',styles['Body2']),Spacer(1,6),Paragraph('7. Reproducibility and Repository',styles['H']),Paragraph('All training, cross-validation and inference code, personalised datasets, fitted models, results and this report are included in the GitHub repository:',styles['Body2']),Paragraph('https://github.com/car-ui/ML-Assignment',styles['Body2']),Spacer(1,6),Paragraph('The main scripts are evaluate.py for model comparison, train.py for fitting the selected models on all training data, and predict.py for generating the required CSV files. The dependency list is provided in requirements.txt.',styles['Body2'])]
story += [PageBreak(),Paragraph('8. Conclusion',styles['H']),Paragraph('The comparison confirms that the best regularisation method depends on the personalised dataset. Lasso performs best for var1, while Ridge performs best for var2. Selecting among Linear, Ridge and Lasso using the same five-fold cross-validation protocol avoids assuming a particular regulariser beforehand. The final models were chosen by validation MSE, then retrained on all available training data before producing the test predictions.',styles['Body2']),Spacer(1,8),Paragraph('Final submission files',styles['H']),Paragraph('1. BT2024108_pred_var1.csv<br/>2. BT2024108_pred_var2.csv<br/>3. BT2024108_Polynomial_Regression_Report.pdf',styles['Body2']),Spacer(1,10),Paragraph('GitHub: https://github.com/car-ui/ML-Assignment',styles['Body2'])]
doc.build(story)
print(path)
